<script lang="ts">
 import {dashboardText} from "$lib/i18n/dashboard.svelte";
 import {useQuery,useConvexClient} from 'convex-svelte';import {api} from '$convex/_generated/api';import type {Id} from '$convex/_generated/dataModel';import {naira} from '$ui/format';
 const client=useConvexClient(),emails=useQuery(api.emailDelivery.queue,{}),payments=useQuery(api.gateways.reconciliationQueue,{});let busy=$state(false),message=$state(''),charges=$state<Record<string,string>>({});
 async function refresh(){busy=true;try{await client.mutation(api.emailDelivery.refreshNow,{});message='Delivery checks queued. Accepted requests remain distinct from delivered messages.';}catch(e){message=e instanceof Error?e.message:'Refresh failed';}finally{busy=false;}}
 async function verify(paymentId:Id<'payments'>){busy=true;try{const result=await client.action(api.gateways.verify,{paymentId,...(charges[paymentId]?{chargeId:charges[paymentId]}:{})});message='Provider result: '+result.status;}catch(e){message=e instanceof Error?e.message:'Verification failed';}finally{busy=false;}}
</script>
<section class="panel p-5 mb-5"><h2 class="text-xl font-semibold">{dashboardText("Payment reconciliation")}</h2><p class="muted text-sm mt-2">{dashboardText("Recent pending orders. Verification checks the provider receipt, amount, currency and order ownership before settlement.")}</p>{#each payments.data??[] as payment}<div class="panel-sunk p-3 mt-3"><p class="break-all">{payment.reference} · {naira(Number(payment.amount))}</p><p class="text-sm muted">{payment.gateway??'No gateway selected'} · {payment.state??'Not initialized'}</p>{#if payment.gateway==='flutterwave'}<input aria-label="Flutterwave charge ID" class="ctl mt-2" bind:value={charges[payment.id]} placeholder="chg_…" />{/if}{#if payment.gateway}<button class="ctl mt-2" disabled={busy} onclick={()=>verify(payment.id)}>{dashboardText("Verify provider receipt")}</button>{/if}</div>{/each}</section>
<section class="panel p-5 mb-5"><h2 class="text-xl font-semibold">{dashboardText("Email delivery outcomes")}</h2><p class="muted text-sm mt-2">{dashboardText("A provider acceptance does not establish inbox delivery. These statuses come from Resend.")}</p><button class="ctl mt-3" disabled={busy} onclick={refresh}>{dashboardText("Refresh delivery outcomes")}</button>{#each emails.data??[] as email}<div class="panel-sunk p-3 mt-3"><p>{email.kind} · <strong>{email.status}</strong></p><p class="text-sm muted">{dashboardText("Accepted")} {new Date(email.acceptedAt).toLocaleString()} · {email.providerId}</p></div>{/each}</section>{#if message}<p role="status" class="mb-5">{message}</p>{/if}
